using System;
using System.Collections.Generic;
using System.CommandLine;
using System.CommandLine.Parsing;
using System.Linq;
using System.Text.Json.Nodes;

namespace Dotenvx.Help;

/// <summary>One `.option(...)` of a command as commander registered it (generated by scripts/gen-help-spec.js).</summary>
public sealed class OptionRegistration
{
    public string Attribute { get; set; } = "";
    public string? Long { get; set; }
    public string? Short { get; set; }
    public bool Negate { get; set; }
    public bool Variadic { get; set; }
    public string Takes { get; set; } = "none";
    public bool HasDefault { get; set; }
    public JsonNode? Default { get; set; }
    public string? Parser { get; set; }
}

/// <remarks>
/// Reference source: commander's `Command.opts()` as the upstream actions print it (`options: ${JSON.stringify(options)}`).
/// commander seeds the object with every default in registration order (a negated option such as `--no-armor` defaults to
/// true unless the positive flag is registered too), then each option the command line sets is assigned in the order they were
/// first given: a flag becomes true (false when negated), a value option takes its last value, a variadic option collects every
/// value, and dotenvx's own collectors (`collectEnvs`, `collectEnvKeys` of src/cli/dotenvx.js) shape `--env`, `--env-file` and
/// `--env-keys-file`. The registrations come from help-spec.json.
/// </remarks>
public static class CommanderOpts
{
    /// <summary>`this.opts()` of the command <paramref name="parseResult" /> runs.</summary>
    public static JsonObject Build(ParseResult parseResult)
    {
        var path = new List<string>();
        for (SymbolResult? result = parseResult.CommandResult; result is CommandResult command; result = result.Parent)
        {
            if (command.Parent is not null)
            {
                path.Insert(0, command.Command.Name);
            }
        }

        HelpSpec? spec = CommanderHelp.Find(path);
        var options = new JsonObject();
        if (spec is null)
        {
            return options;
        }

        foreach (OptionRegistration registration in spec.Registrations)
        {
            if (registration.Negate)
            {
                string positive = "--" + (registration.Long ?? "")["--no-".Length..];
                if (spec.Registrations.All(other => other.Long != positive))
                {
                    options[registration.Attribute] = registration.HasDefault ? registration.Default?.DeepClone() : JsonValue.Create(true);
                }
            }
            else if (registration.HasDefault)
            {
                options[registration.Attribute] = registration.Default?.DeepClone();
            }
        }

        var tokens = parseResult.Tokens.ToList();
        IEnumerable<OptionResult> given = parseResult.CommandResult.Children.OfType<OptionResult>().Where(result => result.IdentifierToken is not null)
            .OrderBy(result => result.IdentifierToken is { } token ? tokens.IndexOf(token) : int.MaxValue);
        foreach (OptionResult result in given)
        {
            OptionRegistration? registration = spec.Registrations.FirstOrDefault(candidate => Matches(candidate, result.Option));
            if (registration is null)
            {
                continue;
            }

            string[] values = [.. result.Tokens.Select(token => token.Value)];
            options[registration.Attribute] = Fold(registration, values, options[registration.Attribute]);
        }

        return options;
    }

    /// <summary>
    /// The env-driven adjustments the actions apply to `this.opts()` before using it: normalizeDotenvConfigQuiet (DOTENV_QUIET)
    /// when <paramref name="quiet" />, then normalizeDotenvConfigConvention (DOTENV_CONVENTION) and normalizeDotenvConfigIgnore
    /// (DOTENV_IGNORE) when <paramref name="conventionAndIgnore" />.
    /// </summary>
    public static JsonObject Normalize(JsonObject options, bool quiet, bool conventionAndIgnore)
    {
        if (quiet)
        {
            if ((Environment.GetEnvironmentVariable("DOTENV_QUIET") ?? Environment.GetEnvironmentVariable("DOTENV_CONFIG_QUIET")) == "true")
            {
                options["quiet"] = true;
            }
        }

        if (conventionAndIgnore)
        {
            string? convention = Environment.GetEnvironmentVariable("DOTENV_CONVENTION");
            if (string.IsNullOrEmpty(convention))
            {
                convention = Environment.GetEnvironmentVariable("DOTENV_CONFIG_CONVENTION");
            }

            if (!string.IsNullOrEmpty(convention) && (options["convention"] is null || options["convention"]?.GetValue<string>() == ""))
            {
                options["convention"] = convention;
            }

            string[] configIgnore =
            [
                .. (Environment.GetEnvironmentVariable("DOTENV_IGNORE") ?? Environment.GetEnvironmentVariable("DOTENV_CONFIG_IGNORE") ?? "")
                    .Split(',').Select(code => code.Trim()).Where(code => code.Length > 0)
            ];
            if (configIgnore.Length > 0)
            {
                var merged = new JsonArray();
                if (options["ignore"] is JsonArray existing)
                {
                    foreach (JsonNode? item in existing)
                    {
                        merged.Add(item?.DeepClone());
                    }
                }

                foreach (string code in configIgnore)
                {
                    merged.Add(code);
                }

                options["ignore"] = merged;
            }
        }

        return options;
    }

    private static bool Matches(OptionRegistration registration, Option option)
    {
        IEnumerable<string> names = [option.Name, .. option.Aliases];

        return names.Any(name => name == registration.Long || (registration.Short is not null && name == registration.Short));
    }

    private static JsonNode? Fold(OptionRegistration registration, string[] values, JsonNode? current)
    {
        if (registration.Takes == "none")
        {
            return JsonValue.Create(!registration.Negate);
        }

        if (registration.Takes == "optional" && values.Length == 0)
        {
            return JsonValue.Create(true);
        }

        switch (registration.Parser)
        {
            case "envFile":
                {
                    JsonArray array = AsArray(current);
                    foreach (string value in values)
                    {
                        foreach (string item in value.Split(',').Select(part => part.Trim()).Where(part => part.Length > 0))
                        {
                            array.Add(item);
                        }
                    }

                    return array;
                }
            case "env":
                {
                    JsonArray array = AsArray(current);
                    foreach (string value in values)
                    {
                        array.Add(value);
                    }

                    return array;
                }
            case "envKeys":
                {
                    JsonNode? previous = current;
                    foreach (string value in values)
                    {
                        previous = previous switch
                        {
                            null => JsonValue.Create(value),
                            JsonArray existing => new JsonArray([.. existing.Select(item => item?.DeepClone()), JsonValue.Create(value)]),
                            _ => new JsonArray(previous.DeepClone(), JsonValue.Create(value))
                        };
                    }

                    return previous;
                }
        }

        if (registration.Variadic)
        {
            return new JsonArray([.. values.Select(value => (JsonNode?)JsonValue.Create(value))]);
        }

        return values.Length == 0 ? current : JsonValue.Create(values[^1]);
    }

    private static JsonArray AsArray(JsonNode? current)
    {
        return current is JsonArray existing
            ? new JsonArray([.. existing.Select(item => item?.DeepClone())])
            : new JsonArray();
    }
}
